		for _, pos := range positions {
			if pos.IsValid() && (file == "" || pos.Filename() == file) {
				return Location{File: file, Line: pos.Line(), Column: pos.Column()}
			}
		}
	}

	message := err.Error()
	if file != "" {
		message = strings.TrimPrefix(message, file+":")
	}
