	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}

	cerrs := make([]Error, 0)
	for _, file := range files {
		b, readErr := os.ReadFile(file)
		if readErr != nil {
			cerrs = append(cerrs, Error{
				Path:     "$",
				Message:  fmt.Sprintf("failed to read file: %v", readErr),
				Location: Location{File: file},
			})
			continue
		}
		result, validationErr := validator.Validate(file, b)
		if validationErr != nil && !errors.Is(validationErr, ErrValidationFailed) {
			return validationErr
		}
		cerrs = append(cerrs, result.Errors...)
	}

